script:
(function () {
  'use strict';
  // Taxable Social Security benefits, following IRS Pub. 915 Worksheet 1 line by line:
  //   provisional ("combined") income = 50% of benefits + other taxable income + tax-exempt interest
  //     + exclusions - adjustments (line 8)
  //   Over the first base amount: taxable = smaller of 50% of benefits or 50% of the excess up to the
  //     second base; above the second base add 85% of the excess; the total is capped at 85% of benefits.
  //   Married filing separately and living with your spouse at any time in the year: 85% of line 8,
  //     capped at 85% of benefits.
  // Verified (Node, scratch tests, against the filled-in worksheets in Pub. 915 (2025)):
  //   Example 1: single, benefits $5,980, other income $28,990 -> line 8 $31,980, taxable $2,990.
  //   Example 2: MFJ, benefits $5,600, income $29,750, $1,000 IRA deduction -> taxable $0.
  //   Jamie/Jessie example: MFJ, benefits $10,000, income $40,500 -> line 8 $45,500, taxable $6,275.
  //   Example 4: MFS living together, benefits $4,000, wages $8,000 -> taxable $3,400.
  //   Also matches income-tax-calculator: single, $30,000 benefits + $20,000 pension -> $5,350.
  //
  // ---- BASE AMOUNTS (tax year 2026) ----------------------------------------------------------
  // $25,000 / $32,000 (50% tier) and $34,000 / $44,000 (85% tier) are fixed by law (IRC 86(c)) and
  //   are not adjusted for inflation; same figures in IRS Pub. 915 Worksheet 1, lines 9 and 11
  //   (lines 11 hold the $9,000 / $12,000 gaps between the two tiers).
  var TAX_YEAR = 2026;
  var BASE = { // [first base, gap to second base]
    single: [25000, 9000], hoh: [25000, 9000], qss: [25000, 9000], mfsApart: [25000, 9000],
    mfj: [32000, 12000], mfsTogether: null
  };
  // -----------------------------------------------------------------------------------------------

  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var whole = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

  function el(id) { return document.getElementById(id); }
  function raw(id) { return el(id).value.trim() === '' ? 0 : parseFloat(el(id).value); }

  // Returns every worksheet line (null = line skipped) and the taxable amount.
  function worksheet(o) {
    var L = {};
    L[1] = o.benefits; L[2] = 0.5 * L[1];
    L[3] = o.otherIncome; L[4] = o.taxExempt; L[5] = o.exclusions;
    L[6] = L[2] + L[3] + L[4] + L[5]; L[7] = o.adjustments;
    for (var k = 8; k <= 19; k++) L[k] = null;
    if (L[1] <= 0) { L[19] = 0; return { L: L, taxable: 0, stop: 'No benefits entered.' }; }
    if (L[7] >= L[6]) { L[19] = 0; return { L: L, taxable: 0, stop: 'Your income after adjustments is zero or less, so none of your benefits are taxable.' }; }
    L[8] = L[6] - L[7];
    L[18] = 0.85 * L[1];
    var b = BASE[o.status];
    if (!b) { L[17] = 0.85 * L[8]; L[19] = Math.min(L[17], L[18]); return { L: L, taxable: L[19], stop: '' }; }
    L[9] = b[0];
    if (L[8] <= L[9]) { L[18] = null; L[19] = 0; return { L: L, taxable: 0, stop: 'Your provisional income is not above the base amount, so none of your benefits are taxable.' }; }
    L[10] = L[8] - L[9]; L[11] = b[1];
    L[12] = Math.max(0, L[10] - L[11]); L[13] = Math.min(L[10], L[11]);
    L[14] = 0.5 * L[13]; L[15] = Math.min(L[2], L[14]); L[16] = 0.85 * L[12];
    L[17] = L[15] + L[16]; L[19] = Math.min(L[17], L[18]);
    return { L: L, taxable: L[19], stop: '' };
  }

  var LINES = [
    [1, 'Total net benefits (Form SSA-1099, box 5)'], [2, 'Half of your benefits'],
    [3, 'Other taxable income'], [4, 'Tax-exempt interest'], [5, 'Excluded income added back'],
    [6, 'Lines 2 to 5 added together'], [7, 'Adjustments to income'],
    [8, 'Provisional income (line 6 minus line 7)'], [9, 'First base amount'],
    [10, 'Provisional income above the first base'], [11, 'Gap between the first and second base'],
    [12, 'Provisional income above the second base'], [13, 'Smaller of line 10 or line 11'],
    [14, 'Half of line 13'], [15, 'Smaller of line 2 or line 14'], [16, '85% of line 12'],
    [17, 'Line 15 plus line 16'], [18, '85% of your benefits (the maximum taxable)'],
    [19, 'Taxable benefits: smaller of line 17 or line 18']
  ];

  function cell(text) { var td = document.createElement('td'); td.textContent = text; return td; }

  function update() {
    var o = {
      status: el('sbStatus').value, benefits: raw('sbBenefits'), taxExempt: raw('sbTaxExempt'),
      wages: raw('sbWages'), pensions: raw('sbPensions'), interest: raw('sbInterest'), otherInc: raw('sbOther'),
      adjustments: raw('sbAdjust'), exclusions: raw('sbExclusions')
    };
    var error = el('sbError');
    var amounts = [o.benefits, o.taxExempt, o.wages, o.pensions, o.interest, o.adjustments, o.exclusions];
    var bad = amounts.some(function (v) { return isNaN(v) || !isFinite(v) || v < 0 || v > 1e10; }) ||
              isNaN(o.otherInc) || !isFinite(o.otherInc) || Math.abs(o.otherInc) > 1e10;
    error.hidden = !bad;
    if (bad) { error.textContent = 'Enter amounts of $0 or more (only other income can be negative, for a loss).'; return; }
    o.otherIncome = o.wages + o.pensions + o.interest + o.otherInc;

    var r = worksheet(o), L = r.L;
    el('sbTaxable').textContent = money.format(r.taxable);
    el('sbShare').textContent = o.benefits > 0 ? (r.taxable / o.benefits * 100).toFixed(1).replace(/\.0$/, '') + '%' : '0%';
    el('sbTaxFree').textContent = money.format(Math.max(0, o.benefits - r.taxable));
    el('sbProvisional').textContent = L[8] === null ? money.format(Math.max(0, L[6] - L[7])) : money.format(L[8]);
    var b = BASE[o.status];
    el('sbBases').textContent = b ? whole.format(b[0]) + ' and ' + whole.format(b[0] + b[1]) : 'None: up to 85% from the first dollar';
    var room = el('sbRoom');
    var prov = L[8] === null ? L[6] - L[7] : L[8];
    if (o.benefits <= 0) room.textContent = '–';
    else if (b && prov < b[0]) room.textContent = whole.format(b[0] - prov) + ' more before any benefits are taxed';
    else {
      var step = 100, r2 = worksheet({ status: o.status, benefits: o.benefits, otherIncome: o.otherIncome + step,
        taxExempt: o.taxExempt, exclusions: o.exclusions, adjustments: o.adjustments });
      var per = Math.max(0, (r2.taxable - r.taxable) / step);
      if (per >= 0.005) room.textContent = '$' + per.toFixed(2) + ' more taxable benefits per extra $1 of income';
      else if (b && prov < b[0] + b[1]) room.textContent = 'Capped at 50% of benefits until income rises ' + whole.format(b[0] + b[1] - prov) + ' more';
      else room.textContent = 'Already at the 85% maximum';
    }
    var note = el('sbNote');
    note.hidden = !r.stop;
    note.textContent = r.stop;

    var body = el('sbWorksheet');
    while (body.firstChild) body.removeChild(body.firstChild);
    LINES.forEach(function (ln) {
      var tr = document.createElement('tr');
      tr.appendChild(cell(String(ln[0])));
      tr.appendChild(cell(ln[1]));
      tr.appendChild(cell(L[ln[0]] === null ? '–' : money.format(L[ln[0]])));
      if (ln[0] === 8 || ln[0] === 19) tr.className = 'font-semibold';
      body.appendChild(tr);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('sbForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
